const NSC_CATEGORIES=[{key:"rifle",name:"Rifle",icon:"🎯",blurb:"Precision long-range marksmanship"},{key:"pistol",name:"Pistol",icon:"🔫",blurb:"Rapid and precision handgun events"},{key:"shotgun",name:"Shotgun",icon:"💥",blurb:"Moving-target clay pigeon shooting"},{key:"para",name:"Para",icon:"♿",blurb:"Adaptive shooting for differently-abled athletes"}],NSC_REGIONS=[{key:"north",name:"North India",icon:"🏔️"},{key:"south",name:"South India",icon:"🌴"},{key:"east",name:"East India",icon:"🌾"},{key:"west",name:"West India",icon:"🏜️"},{key:"northeast",name:"Northeast India",icon:"🌿"},{key:"central",name:"Central India",icon:"🏛️"},{key:"pan",name:"Pan-India",icon:"🇮🇳"}],NSC_ATHLETES=[{name:"Abhinav Bindra",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Abhinav_Bindra_and_Mary_Kom_-_British_High_Commission%2C_Delhi%2C_27_July_2011_%28cropped%29.jpg/330px-Abhinav_Bindra_and_Mary_Kom_-_British_High_Commission%2C_Delhi%2C_27_July_2011_%28cropped%29.jpg",category:"rifle",event:"10m Air Rifle",region:"north",state:"Punjab",born:1982,tagline:"India's first individual Olympic gold medallist",desc:"Abhinav Bindra won the gold medal in the 10m Air Rifle event at the 2008 Beijing Olympics, becoming the first Indian to win an individual Olympic gold medal. He held the world record and dominated the discipline for over a decade.",achievements:["Olympic Gold 2008 (10m Air Rifle)","World Champion 2006","Commonwealth Games Gold 2002, 2006","Multiple ISSF World Cup medals"],records:"Former World Record holder in 10m Air Rifle",olympic:!0,active:!1,sources:["International Shooting Sport Federation (ISSF)","National Rifle Association of India (NRAI)"]},{name:"Gagan Narang",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/XIX_Commonwealth_Games-2010_Delhi_Gagan_Narang_won_the_Gold_medal_in_%28Men%E2%80%99s%29_Shooting_Rifle_50m_pairs_%28cropped%29.jpg/400px-XIX_Commonwealth_Games-2010_Delhi_Gagan_Narang_won_the_Gold_medal_in_%28Men%E2%80%99s%29_Shooting_Rifle_50m_pairs_%28cropped%29.jpg",category:"rifle",event:"10m Air Rifle / 50m Rifle 3 Positions",region:"south",state:"Andhra Pradesh",born:1983,tagline:"Olympic bronze medallist and multi-discipline champion",desc:"Gagan Narang won the bronze medal in the 10m Air Rifle at the 2012 London Olympics. He has been one of India's most consistent shooters, winning medals across multiple ISSF World Cups and Commonwealth Games.",achievements:["Olympic Bronze 2012 (10m Air Rifle)","Commonwealth Games Gold 2006, 2010","ISSF World Cup medals","Arjuna Award 2005"],records:"Multiple national records in rifle events",olympic:!0,active:!1,sources:["ISSF","NRAI"]},{name:"Anjali Bhagwat",icon:"🏅",img:"",category:"rifle",event:"10m Air Rifle / 50m Rifle 3 Positions",region:"west",state:"Maharashtra",born:1969,tagline:"Pioneer of Indian women's rifle shooting",desc:"Anjali Bhagwat was one of the first Indian women to achieve international success in shooting. She won multiple medals at ISSF World Cups and Asian Games, paving the way for future generations of Indian women shooters.",achievements:["ISSF World Cup medals","Asian Games medal","Commonwealth Games medals","Arjuna Award 2001"],records:"Multiple national records",olympic:!0,active:!1,sources:["ISSF","NRAI"]},{name:"Swapnil Kusale",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/b/b3/Swapnil_Kusale_in_August_2024_with_his_Paris_Olympics_bronze_medal.jpg",category:"rifle",event:"50m Rifle 3 Positions",region:"west",state:"Maharashtra",born:1995,tagline:"Paris 2024 bronze medallist in 50m Rifle 3 Positions",desc:"Swapnil Kusale won India's third shooting medal at the 2024 Paris Olympics with a bronze in the 50m Rifle 3 Positions event. His calm composure under pressure made him one of India's elite rifle shooters.",achievements:["Olympic Bronze 2024 (50m Rifle 3 Positions)","Asian Games competitor","ISSF World Cup medal"],records:"",olympic:!0,active:!0,sources:["ISSF","NRAI"]},{name:"Chain Singh",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Chain_Singh_%282016%29.jpg/400px-Chain_Singh_%282016%29.jpg",category:"rifle",event:"50m Rifle 3 Positions",region:"north",state:"Haryana",born:1991,tagline:"Asian Games gold medallist in rifle shooting",desc:"Chain Singh won gold at the 2014 Asian Games in Incheon in the 50m Rifle 3 Positions event. He has been a consistent performer at international competitions representing India.",achievements:["Asian Games Gold 2014","ISSF World Cup medals","Commonwealth Games medals"],records:"",olympic:!1,active:!0,sources:["ISSF","NRAI"]},{name:"Manu Bhaker",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/f/f1/Paris_Olympics_double_bronze_medalist_Manu_Bhaker_in_August_2024.jpg",category:"pistol",event:"10m Air Pistol / 25m Sport Pistol",region:"north",state:"Haryana",born:2002,tagline:"Double Olympic bronze medallist at Paris 2024",desc:"Manu Bhaker became India's most decorated Olympic shooter at the 2024 Paris Olympics, winning two bronze medals — one in the 10m Air Pistol and one in the 10m Air Pistol Mixed Team event with Sarabjot Singh. She became the youngest Indian to win an Olympic shooting medal.",achievements:["Olympic Bronze 2024 (10m Air Pistol)","Olympic Bronze 2024 (Mixed Team)","ISSF World Cup medals","Youth Olympic Gold 2018","Asian Games medals"],records:"Youngest Indian Olympic shooting medallist",olympic:!0,active:!0,sources:["ISSF","NRAI"]},{name:"Sarabjot Singh",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/7/79/Sarabjot_Singh_in_August_2024_with_his_Paris_Olympics_bronze_medal.jpg",category:"pistol",event:"10m Air Pistol",region:"north",state:"Haryana",born:2001,tagline:"Olympic bronze medallist in mixed team pistol",desc:"Sarabjot Singh won the Olympic bronze medal in the 10m Air Pistol Mixed Team event alongside Manu Bhaker at the 2024 Paris Olympics. His steady performances made him a key member of India's pistol squad.",achievements:["Olympic Bronze 2024 (Mixed Team)","ISSF World Cup medals","Asian Games competitor"],records:"",olympic:!0,active:!0,sources:["ISSF","NRAI"]},{name:"Heena Sidhu",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/f/fb/Heena_Sidhu%2C_promo_for_2014_CWG.jpg",category:"pistol",event:"10m Air Pistol / 25m Sport Pistol",region:"north",state:"Punjab",born:1989,tagline:"Former world record holder in 10m Air Pistol",desc:"Heena Sidhu made history by becoming the first Indian pistol shooter to hold the world record in the 10m Air Pistol event. She won multiple medals at ISSF World Cups and Asian Games, becoming a trailblazer for women's pistol shooting in India.",achievements:["Former World Record holder","ISSF World Cup Gold","Asian Games medal","Commonwealth Games Gold","Arjuna Award 2014"],records:"Former World Record in 10m Air Pistol (Women)",olympic:!0,active:!1,sources:["ISSF","NRAI"]},{name:"Rahi Sarnobat",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/a/a0/Rahi_Sarnobat.jpg",category:"pistol",event:"25m Sport Pistol",region:"west",state:"Maharashtra",born:1991,tagline:"Asian Games gold medallist in 25m Sport Pistol",desc:"Rahi Sarnobat became the first Indian woman pistol shooter to win an Asian Games gold medal, achieving this feat at the 2018 Asian Games in Jakarta. She has been a consistent performer on the ISSF World Cup circuit.",achievements:["Asian Games Gold 2018","ISSF World Cup medals","Commonwealth Games Gold","Arjuna Award 2019"],records:"",olympic:!0,active:!0,sources:["ISSF","NRAI"]},{name:"Anisa Sayyed",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Anisa_Sayyed_of_India_won_the_gold_medal_in_25M_Pistol_Women_%28Pair%29_event%2C_at_Karnail_Singh_Shooting_Range%2C_in_New_Delhi_on_October_05%2C_2010_%28cropped%29.jpg/330px-Anisa_Sayyed_of_India_won_the_gold_medal_in_25M_Pistol_Women_%28Pair%29_event%2C_at_Karnail_Singh_Shooting_Range%2C_in_New_Delhi_on_October_05%2C_2010_%28cropped%29.jpg",category:"pistol",event:"25m Sport Pistol / 10m Air Pistol",region:"west",state:"Maharashtra",born:1980,tagline:"Multiple-time national champion in pistol events",desc:"Anisa Sayyed has been one of India's most decorated pistol shooters, winning multiple National Championship titles and representing India at Asian Games and World Championships. She has been a mentor to younger pistol shooters.",achievements:["Multiple National Championship titles","Asian Games competitor","Commonwealth Games medals"],records:"",olympic:!1,active:!1,sources:["NRAI"]},{name:"Rajyavardhan Singh Rathore",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/The_Minister_of_State_for_Youth_Affairs_and_Sports_%28IC%29_and_Information_%26_Broadcasting%2C_Col._Rajyavardhan_Singh_Rathore_addressing_after_felicitating_the_winners_of_the_World_Youth_Boxing_Championship_2017%2C_at_a_function_%28cropped%29.jpg/400px-thumbnail.jpg",category:"shotgun",event:"Double Trap",region:"north",state:"Rajasthan",born:1967,tagline:"India's first individual Olympic silver medallist",desc:"Colonel Rajyavardhan Singh Rathore won the silver medal in Double Trap at the 2004 Athens Olympics, becoming the first Indian to win an individual Olympic medal. He later served as a Union Minister and continues to promote shooting sports.",achievements:["Olympic Silver 2004 (Double Trap)","Asian Games Gold 2002","Commonwealth Games Gold","Padma Shri 2004"],records:"First individual Olympic medal for India",olympic:!0,active:!1,sources:["ISSF","NRAI"]},{name:"Jaspal Rana",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Shri_Jaspal_Rana_%28ONGC%29%2C_Shooter%2C_in_2007_%28cropped%29.jpg/400px-Shri_Jaspal_Rana_%28ONGC%29%2C_Shooter%2C_in_2007_%28cropped%29.jpg",category:"pistol",event:"25m Center Fire Pistol",region:"north",state:"Uttarakhand",born:1976,tagline:"Asian Games gold medallist and national champion",desc:"Jaspal Rana won gold at the 1994 Asian Games in Hiroshima in the 25m Center Fire Pistol event at the age of just 18. He went on to win multiple medals at Asian Games and Commonwealth Games, becoming one of India's most successful pistol shooters.",achievements:["Asian Games Gold 1994, 2002","Commonwealth Games Gold","Multiple National Championship titles","Arjuna Award"],records:"",olympic:!0,active:!1,sources:["ISSF","NRAI"]},{name:"Kynan Chenai",icon:"🏅",img:"",category:"shotgun",event:"Trap",region:"south",state:"Telangana",born:1991,tagline:"Commonwealth Games medal in Trap shooting",desc:"Kynan Chenai won a bronze medal at the 2018 Commonwealth Games in Gold Coast in the Trap event. He has represented India at multiple ISSF World Cups and Asian Championships.",achievements:["Commonwealth Games Bronze 2018","ISSF World Cup competitor","Asian Championship medals"],records:"",olympic:!0,active:!0,sources:["ISSF","NRAI"]},{name:"Mairaj Ahmad Khan",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Mairaj_Ahmad_Khan_in_skeet_at_the_2020_Summer_Olympic_Games_%2851352316344%29_%28cropped%29.jpg/400px-Mairaj_Ahmad_Khan_in_skeet_at_the_2020_Summer_Olympic_Games_%2851352316344%29_%28cropped%29.jpg",category:"shotgun",event:"Skeet",region:"north",state:"Delhi",born:1972,tagline:"India's most successful skeet shooter",desc:"Mairaj Ahmad Khan has been India's leading skeet shooter, winning multiple National Championship titles and representing India at Asian Games and World Championships. He qualified for the 2012 London Olympics.",achievements:["Olympic qualifier 2012","Asian Games medals","Multiple National Championship titles"],records:"",olympic:!0,active:!1,sources:["ISSF","NRAI"]},{name:"Avani Lekhara",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/8/8a/Avani_Lekhara_in_2022.jpg",category:"para",event:"10m Air Rifle Standing / 50m Rifle 3 Positions",region:"north",state:"Rajasthan",born:2001,tagline:"Paralympic gold medallist and world record holder",desc:"Avani Lekhara won the gold medal in the R2 10m Air Rifle Standing SH1 event at the 2020 Tokyo Paralympics, becoming the first Indian woman to win a Paralympic gold medal. She also won a bronze in the R8 50m Rifle 3 Positions SH1 event.",achievements:["Paralympic Gold 2020 (10m Air Rifle Standing)","Paralympic Bronze 2020 (50m Rifle 3 Positions)","World Record holder","Khel Ratna 2021"],records:"World Record in R2 10m Air Rifle Standing SH1",olympic:!1,active:!0,sources:["World Shooting Para Sport","Paralympic Committee of India"]},{name:"Manish Narwal",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/c/c8/Manish_Narwal_in_September_2024.jpg",category:"para",event:"10m Air Pistol / 50m Pistol",region:"north",state:"Haryana",born:2001,tagline:"Paralympic gold medallist in pistol",desc:"Manish Narwal won the gold medal in the P4 50m Pistol SH1 event at the 2020 Tokyo Paralympics. He has been one of India's most consistent para shooting athletes, winning multiple international medals.",achievements:["Paralympic Gold 2020 (50m Pistol SH1)","Asian Para Games Gold","ISSF World Cup medals"],records:"",olympic:!1,active:!0,sources:["World Shooting Para Sport","Paralympic Committee of India"]},{name:"Singhraj Adhana",icon:"🏅",img:"",category:"para",event:"10m Air Pistol / 50m Pistol",region:"north",state:"Haryana",born:1982,tagline:"Paralympic bronze medallist in pistol",desc:"Singhraj Adhana won the bronze medal in the P1 10m Air Pistol SH1 event at the 2020 Tokyo Paralympics, adding to India's historic para shooting haul. He also won gold at the 2022 Asian Para Games.",achievements:["Paralympic Bronze 2020 (10m Air Pistol SH1)","Asian Para Games Gold 2022","ISSF World Cup medals"],records:"",olympic:!1,active:!0,sources:["World Shooting Para Sport","Paralympic Committee of India"]},{name:"Anish Bhanwala",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Anish_Bhanwala%2C_Gold_Medal_Winner_of_the_Commonwealth_Games-2018%2C_in_New_Delhi_%28cropped%29.JPG/330px-Anish_Bhanwala%2C_Gold_Medal_Winner_of_the_Commonwealth_Games-2018%2C_in_New_Delhi_%28cropped%29.JPG",category:"pistol",event:"25m Rapid Fire Pistol",region:"north",state:"Haryana",born:2002,tagline:"Gold medallist at 2018 Commonwealth Games",desc:"Anish Bhanwala became the youngest Indian to win a Commonwealth Games gold medal at the 2018 Gold Coast Games in the 25m Rapid Fire Pistol event at the age of 15.",achievements:["Commonwealth Games Gold 2018","Asian Games competitor","ISSF World Cup medals"],records:"Youngest Indian CWG gold medallist (at the time)",olympic:!1,active:!0,sources:["ISSF","NRAI"]},{name:"Saurabh Chaudhary",icon:"🏅",img:"https://upload.wikimedia.org/wikipedia/commons/3/35/Saurabh_Chaudhary_2025.jpg",category:"pistol",event:"10m Air Pistol",region:"north",state:"Uttar Pradesh",born:2002,tagline:"Youth Olympic gold medallist and World Cup champion",desc:"Saurabh Chaudhary won gold at the 2018 Youth Olympics in Buenos Aires in the 10m Air Pistol event. He has won multiple ISSF World Cup medals and was part of India's mixed team events.",achievements:["Youth Olympic Gold 2018","ISSF World Cup Gold","Asian Games Gold 2018 (Mixed Team)"],records:"",olympic:!0,active:!0,sources:["ISSF","NRAI"]}],NSC_HISTORY=[{year:1957,event:"First National Shooting Championship",desc:"The inaugural National Shooting Championship was held, marking the beginning of organized competitive shooting in India.",icon:"🏛️"},{year:1961,event:"NRAI Affiliation with ISSF",desc:"The National Rifle Association of India became affiliated with the International Shooting Sport Federation, connecting Indian shooting to the global stage.",icon:"🌍"},{year:1974,event:"New Delhi World Championship Hosting",desc:"India hosted the ISSF World Shooting Championships in New Delhi, putting Indian shooting on the world map.",icon:"🏟️"},{year:1984,event:"First Olympic Shooting Representation",desc:"Indian shooters made their mark at the 1984 Los Angeles Olympics, setting the stage for future Olympic participation.",icon:"🏅"},{year:1994,event:"Jaspal Rana's Asian Games Gold",desc:"Jaspal Rana won gold at the 1994 Asian Games in Hiroshima at just 18 years old, inspiring a generation of pistol shooters.",icon:"🥇"},{year:2001,event:"NRAI Reorganization",desc:"The NRAI underwent significant reorganization, improving training infrastructure and athlete development programs across the country.",icon:"📋"},{year:2002,event:"Rathore's Asian Games Gold",desc:"Rajyavardhan Singh Rathore won gold in Double Trap at the 2002 Asian Games in Busan, India's first shooting gold at the Asian Games.",icon:"🥇"},{year:2004,event:"Rathore's Olympic Silver",desc:"Rajyavardhan Singh Rathore won silver in Double Trap at the 2004 Athens Olympics — India's first-ever individual Olympic medal in shooting.",icon:"🥈"},{year:2006,event:"Bindra's World Championship Gold",desc:"Abhinav Bindra won gold at the 2006 ISSF World Shooting Championships in Zagreb, signalling his readiness for Olympic glory.",icon:"🏆"},{year:2008,event:"Bindra's Historic Olympic Gold",desc:"Abhinav Bindra won gold in 10m Air Rifle at the 2008 Beijing Olympics — India's first-ever individual Olympic gold medal.",icon:"🥇"},{year:2012,event:"Narang's Olympic Bronze",desc:"Gagan Narang won bronze in 10m Air Rifle at the 2012 London Olympics, continuing India's Olympic shooting medal streak.",icon:"🥉"},{year:2014,event:"Manu Bhaker Begins Career",desc:"Young Manu Bhaker started making waves at national championships, eventually becoming one of India's most decorated Olympic shooters.",icon:"🌟"},{year:2018,event:"Asian Games Record Haul",desc:"Indian shooters won a record number of medals at the 2018 Asian Games in Jakarta, including golds from Manu Bhaker, Rahi Sarnobat, and the mixed team.",icon:"🥇"},{year:2020,event:"Paralympic Shooting Breakthrough",desc:"Avani Lekhara, Manish Narwal, and Singhraj Adhana won three medals at the 2020 Tokyo Paralympics, establishing India as a para shooting powerhouse.",icon:"🏅"},{year:2024,event:"Paris Olympics Triple Medal",desc:"Indian shooters won three bronze medals at the 2024 Paris Olympics — Manu Bhaker (2), Sarabjot Singh, and Swapnil Kusale — India's best-ever Olympic shooting haul.",icon:"🥉"}],NSC_MEDALS=[{event:"Olympics",athlete:"Rajyavardhan Singh Rathore",medal:"Silver",category:"shotgun",event_detail:"Double Trap",year:2004,games:"Athens"},{event:"Olympics",athlete:"Abhinav Bindra",medal:"Gold",category:"rifle",event_detail:"10m Air Rifle",year:2008,games:"Beijing"},{event:"Olympics",athlete:"Gagan Narang",medal:"Bronze",category:"rifle",event_detail:"10m Air Rifle",year:2012,games:"London"},{event:"Olympics",athlete:"Manu Bhaker",medal:"Bronze",category:"pistol",event_detail:"10m Air Pistol",year:2024,games:"Paris"},{event:"Olympics",athlete:"Manu Bhaker & Sarabjot Singh",medal:"Bronze",category:"pistol",event_detail:"10m Air Pistol Mixed Team",year:2024,games:"Paris"},{event:"Olympics",athlete:"Swapnil Kusale",medal:"Bronze",category:"rifle",event_detail:"50m Rifle 3 Positions",year:2024,games:"Paris"},{event:"Paralympics",athlete:"Avani Lekhara",medal:"Gold",category:"para",event_detail:"10m Air Rifle Standing SH1",year:2021,games:"Tokyo"},{event:"Paralympics",athlete:"Avani Lekhara",medal:"Bronze",category:"para",event_detail:"50m Rifle 3 Positions SH1",year:2021,games:"Tokyo"},{event:"Paralympics",athlete:"Manish Narwal",medal:"Gold",category:"para",event_detail:"50m Pistol SH1",year:2021,games:"Tokyo"},{event:"Paralympics",athlete:"Singhraj Adhana",medal:"Bronze",category:"para",event_detail:"10m Air Pistol SH1",year:2021,games:"Tokyo"},{event:"Asian Games",athlete:"Rajyavardhan Singh Rathore",medal:"Gold",category:"shotgun",event_detail:"Double Trap",year:2002,games:"Busan"},{event:"Asian Games",athlete:"Jaspal Rana",medal:"Gold",category:"pistol",event_detail:"25m Center Fire Pistol",year:1994,games:"Hiroshima"},{event:"Asian Games",athlete:"Jaspal Rana",medal:"Gold",category:"pistol",event_detail:"25m Center Fire Pistol",year:2002,games:"Busan"},{event:"Asian Games",athlete:"Chain Singh",medal:"Gold",category:"rifle",event_detail:"50m Rifle 3 Positions",year:2014,games:"Incheon"},{event:"Asian Games",athlete:"Rahi Sarnobat",medal:"Gold",category:"pistol",event_detail:"25m Sport Pistol",year:2018,games:"Jakarta"},{event:"Asian Games",athlete:"Saurabh Chaudhary & Manu Bhaker",medal:"Gold",category:"pistol",event_detail:"10m Air Pistol Mixed Team",year:2018,games:"Jakarta"},{event:"Commonwealth Games",athlete:"Abhinav Bindra",medal:"Gold",category:"rifle",event_detail:"10m Air Rifle",year:2002,games:"Manchester"},{event:"Commonwealth Games",athlete:"Abhinav Bindra",medal:"Gold",category:"rifle",event_detail:"10m Air Rifle",year:2006,games:"Melbourne"},{event:"Commonwealth Games",athlete:"Gagan Narang",medal:"Gold",category:"rifle",event_detail:"10m Air Rifle",year:2010,games:"Delhi"},{event:"Commonwealth Games",athlete:"Heena Sidhu",medal:"Gold",category:"pistol",event_detail:"10m Air Pistol",year:2010,games:"Delhi"},{event:"Commonwealth Games",athlete:"Anish Bhanwala",medal:"Gold",category:"pistol",event_detail:"25m Rapid Fire Pistol",year:2018,games:"Gold Coast"},{event:"Commonwealth Games",athlete:"Kynan Chenai",medal:"Bronze",category:"shotgun",event_detail:"Trap",year:2018,games:"Gold Coast"}],NSC_MILESTONES=[{year:1957,title:"First National Championship",desc:"The National Shooting Championship was established under the NRAI, providing a platform for domestic competition and talent identification."},{year:1974,title:"World Championship in India",desc:"New Delhi hosted the ISSF World Shooting Championships, demonstrating India's capability to organize major international shooting events."},{year:1999,title:"Karni Singh Shooting Range",desc:"The Karni Singh Shooting Range in New Delhi was upgraded to international standards, becoming the premier shooting facility in India."},{year:2003,title:"Olympic Qualification System",desc:"NRAI established a structured Olympic qualification pathway, helping shooters prepare systematically for Games participation."},{year:2010,title:"Delhi Commonwealth Games",desc:"India hosted the Commonwealth Games in Delhi, with shooting events held at the newly upgraded Karni Singh Range. Indian shooters excelled with multiple medals."},{year:2014,title:"Junior Development Program",desc:"NRAI launched an expanded junior development program, identifying and nurturing young shooting talent across all disciplines."},{year:2017,title:"Private Shooting Ranges Expansion",desc:"Multiple private shooting ranges opened across India, democratizing access to the sport and increasing participation at the grassroots level."},{year:2020,title:"Para Shooting Recognition",desc:"Para shooting events received enhanced recognition and support from NRAI, leading to dedicated training programs for para-athletes."},{year:2022,title:"World Championship Hosting",desc:"India continued to host international shooting events, reinforcing its status as a leading shooting nation in Asia."},{year:2024,title:"Historic Paris Olympic Haul",desc:"Indian shooters won three medals at the Paris Olympics, the country's best-ever performance in Olympic shooting, inspiring a new wave of participation."}];